# ЭТАЛОН СПРАВКИ И РУКОВОДСТВА — СТАТИЧЕСКИЙ КОД В GIT.
# Источник: тела статей и разделов из sync-скриптов 0.6.0-0.12.0.
# НЕ генерируется из базы данных: одинаков на любой ОС (Windows/Linux/
# малина). Любой новый сервер получает полную справку и руководство при
# первом же старте. apply() делает upsert по эталону: существующие статьи
# и разделы из этого списка приводятся к эталонному тексту (ручные правки
# в UI временные; постоянные правки делаются здесь + commit).
# Статьи/разделы, которых НЕТ в этом списке, не трогаются вообще.
import json as _json
from datetime import datetime as _dt

_RAW = '''{"help": [{"title": "Что это за программа", "category": "Основы", "order": 0, "body": "Модульное веб-приложение для производственного отдела. Заменяет общую сетевую Excel-таблицу: несколько человек работают одновременно, никто никого не блокирует, все изменения фиксируются.\nВход в систему по логину и паролю; возможности каждого определяются ролью. Данные хранятся в одной базе data/database.db.\nСостав: Задачи отдела (хотелки), Производство (заполняется под вашу таблицу), Журнал изменений, Версии, Справка, Руководство (с печатью), Настройки, Роли и Пользователи.\nПрограмма состоит из ядра и модулей: модуль можно включить или выключить в Настройках, не трогая остальное."}, {"title": "Ядро и модули", "category": "Основы", "order": 1, "body": "Ядро (папка core) отвечает за вход, базу данных, роли, права и общий интерфейс. Модули (папка modules) — отдельные виды учёта со своими таблицами и страницами.\nКаждый модуль сам объявляет свои права в файле perms.py, поэтому новый модуль автоматически появляется в меню, в Настройках и в списке прав на экране «Роли» — ядро править не нужно.\nВключение/выключение модуля: Настройки → блок «Доступные модули» → галочка → Сохранить → перезапустить python run.py. Название, тема и требования применяются сразу, без перезапуска.\nМодуль «Настройки» выключить нельзя."}, {"title": "Вход, пароль и блокировки", "category": "Основы", "order": 2, "body": "Вход: страница входа, логин и пароль. Источник пароля зависит от учётки: локальные проверяются у нас, доменные — в Active Directory (значок 🌐 в профиле и в журнале входов).\nПри первом входе локальная учётка обязана сменить пароль. Доменные пароли меняются в самом AD (Ctrl+Alt+Del → «Сменить пароль»).\nБлокировка подбора: после N неудачных входов подряд вход замирает на M минут (N и M задаются в Настройках). Журнал входов покажет серию отказов, IP и источник (local/ad).\nЕсли включён AD: доменные пользователи входят учётками Windows; при первом входе учётка создаётся автоматически с ролью по умолчанию. Если AD недоступен и включён fallback — локальные пароли продолжают работать.\nЗабыли пароль: локальный сбрасывает администратор в «Пользователи»; доменный меняется в AD. Админ забыл пароль: выключите авторизацию флажком в Настройках, войдите, сбросьте пароль, включите обратно."}, {"title": "Руководство и печать", "category": "Основы", "order": 3, "body": "Руководство по эксплуатации — раздел «Руководство» в меню: разделы от назначения до регламента, с содержанием и якорями.\nПечать: «Руководство» → «Версия для печати» → кнопка «Печать» или Ctrl+P. В бумагу уходит только текст: без меню, кнопок и форм, с титульной строкой (название, версия, дата печати).\nДержите распечатку у руководителя; перепечатывайте после крупных обновлений. Электронная версия всегда свежее; дата и автор обновления — под каждым разделом.\nПравить разделы может роль с правом «Редактировать руководство» (кнопка «Править раздел» под текстом)."}, {"title": "Как работать с Хотелками", "category": "Модули", "order": 0, "body": "Раздел «Задачи отдела» — доска потребностей: сотрудники пишут, что нужно, и указывают адресата; руководитель ведёт статусы.\nПодать хотелку: «Кто» (по умолчанию вы, можно выбрать из списка или вписать), «Кому» (адресат: выберите пользователя из выпадающего списка или впишите своё, например должность), текст → «Отправить».\nПриватность: галочка «приватно» делает запись видимой только автору, адресату и администратору; в списке она помечена замком. Кнопка «Сделать приватной/открытой» есть у автора, адресата и админа. Чужие приватные записи не видны ни в списке, ни в истории, ни в счётчиках.\nСтатусы: Новая, В работе, Сделано, Не нужно; менять может роль с правом «менять статус». При включённом требовании причины отказ «Не нужно» невозможен без комментария.\nКнопка «История» показывает, кто и когда менял статусы (только доступные вам записи). Поиск и фильтры — над таблицей."}, {"title": "Конструктор таблиц: свои таблицы, колонки и формулы", "category": "Модули", "order": 5, "body": "Раздел «Таблицы (конструктор)» позволяет создавать собственные таблицы прямо в программе, без правки кода: как листы Excel, но с правами доступа и историей.\nСоздание таблицы: «Таблицы» → форма «Создать таблицу» (название + ключ латиницей). Далее «Колонки и формулы»: добавляйте колонки с типами текст, число, дата, список (варианты через запятую), вычисляемая (⚙) и ссылка на другую таблицу.\nКонструктор формул (тип «вычисляемая»): выберите вид (арифметика, склейка текста, дней между дат, ЕСЛИ…ТО…ИНАЧЕ), операцию и операнды — ключи колонок или текст/число. Пример результата считается на первой строке сразу при сохранении. Вычисляемые колонки помечены ⚙ и не редактируются руками: их считает программа, всегда актуально, и их нельзя сломать.\nСсылка на другую таблицу (аналог ВПР): укажите таблицу, по какому ключу совпадать здесь и там, и какую колонку показать оттуда.\nПрава на клетки: экран «Доступ (роли × колонки)»: для каждой роли галочки «видит таблицу», «создаёт строки», «удаляет», и отдельные галочки ✎ на каждую колонку, которую роли разрешено менять. Остальные колонки роль видит как 🔒 (только чтение). Суперпользователь видит и меняет всё.\nИстория клеток: каждое изменение ячейки пишется в «Историю клеток» (кто, когда, было → стало). Корзина: удалённые строки хранятся 30 дней, доступны восстановление и удаление навсегда; старше 30 дней удаляются автоматически.\nСчётчики-карточки над таблицей настраиваются в «Колонки и формулы» строками вида: Название|sum|колонка|колонка-условие|значение-условия.\nУдаление таблицы создаёт резервную копию в data/backups/ и фиксируется в журнале.\n\nИмпорт из Excel: кнопка «Импорт Excel» на странице таблицы и в разделе колонок. Выберите .xlsx, укажите лист (пусто = первый) и номер строки заголовков (по умолчанию 1). Колонки сопоставляются по названию заголовка; для несовпавших можно автоматически создать колонки типа «Текст». Пустые строки пропускаются, даты переносятся в виде дд.мм.гггг, по каждой добавленной строке в истории остаётся отметка импорта."}, {"title": "Как включать и выключать модули", "category": "Руководителю", "order": 0, "body": "Настройки → блок «Доступные модули». Снятая галочка убирает модуль из меню и закрывает его адреса; поставленная — возвращает.\nПрименяется после перезапуска python run.py. Это единственное действие в Настройках, требующее перезапуска; всё остальное (название, тема, требования, авторизация) применяется сразу.\nМодуль «Настройки» выключить нельзя: иначе нечем управлять системой.\nПраво менять настройки — settings.manage; оно же позволяет выключить авторизацию, поэтому выдавайте его только руководителю и администратору."}, {"title": "Роли и права: как настроить под должности", "category": "Руководителю", "order": 1, "body": "Роль — набор прав (галочек). Человек получает ровно то, что отмечено в его роли. Права написаны человеческим языком под каждой галочкой.\nСистемные роли: admin (всё автоматически плюс управление людьми, ролями и безопасностью), manager (данные, справочники, журнал, версии, руководство), staff (подаёт задачи, читает остальное), viewer (только чтение).\nСоздать роль: Роли → «Новая роль» → название, описание → галочки прав → «Сохранить». Назначить человеку: Пользователи → «Править» → выбрать роль.\nЗащиты: у admin неснимаемые системные права; свою роль изменить нельзя; системную роль и роль с людьми удалить нельзя.\nПример под должность: роль «Мастер участка» = задачи смотреть+создавать+менять статус, журнал смотреть, остальное без галочек."}, {"title": "Пользователи: создать, закрыть, сбросить пароль", "category": "Руководителю", "order": 2, "body": "Создать: Пользователи → «Новый пользователь» → логин, имя, роль, временный пароль → Сохранить. Временный пароль передайте лично; при первом входе человек обязан его сменить.\nЗакрыть доступ: кнопка «Закрыть» (увольнение, отпуск). «Открыть» возвращает. Причины отказов входа видны в журнале входов.\nСбросить пароль: «Править» → форма «Сбросить пароль». Сброс также снимает временную блокировку после неудачных попыток.\nУдалить: только если человек больше не нужен; его действия останутся в журналах.\nЗащиты: нельзя удалить или закрыть себя и последнего активного администратора."}, {"title": "Журнал входов и аудит действий", "category": "Руководителю", "order": 3, "body": "Журнал входов: Пользователи → «Журнал входов». Видно: когда, кто, успешно или отказ, с какого IP, причина отказа (неверный пароль, закрыт, заблокирован). Просматривайте раз в неделю и после сообщений о проблемах.\nАудит действий над пользователями: лента внизу страницы «Пользователи»: создание, блокировка, сброс пароля, удаление — с именем того, кто нажал.\nЗачем: это ответ на вопросы «кто заходил ночью», «почему человек не может войти», «кто удалил учётку». В сетевом Excel такого не было вообще."}, {"title": "Журнал изменений и версии: как вести", "category": "Руководителю", "order": 4, "body": "Журнал изменений: лента «что добавлено, исправлено, изменено, удалено». Записывает руководитель после каждого изменения программы или порядка работы. Есть фильтры по типу и модулю, поиск и выгрузка в Excel/CSV.\nВерсии: список релизов (номер, дата, что вошло, статус). Текущая версия — в подвале каждой страницы и на странице «О программе». При изменении, заметном людям, создавайте релиз и помечайте его текущим.\nПравило: любое изменение оставляет след в журнале; видимое людям — ещё и в релизе. Тогда через год можно объяснить, почему сделано именно так."}, {"title": "Регламент документации: что обновлять после изменений", "category": "Руководителю", "order": 5, "body": "После каждого изменения программы или порядка работы обновить:\nЖурнал изменений — запись (тип, модуль, описание, кто записал).\nВерсии — новый релиз, если изменение видно людям; пометить текущим.\nСправку — статьи, которых коснулось изменение; новая статья при новом порядке действий.\nРуководство — затронутые разделы; после крупного обновления распечатать.\nREADME на GitHub — если изменились структура, запуск или состав модулей.\nКоманда python sync_docs.py повторно применяет содержимое документации из установщика (статьи справки обновляются всегда при установке). Ответственный — тот, кто вносит изменение. Раз в месяц руководитель просматривает Справку и Руководство на актуальность."}, {"title": "Где база и как делать бэкап", "category": "Техническое", "order": 0, "body": "Все данные — в одном файле data/database.db (папка data внутри папки программы). Путь абсолютный, задаётся в config.py.\nРезервная копия: остановите сервер (Ctrl+C) или копируйте рано утром; скопируйте database.db в сетевую папку или на флешку с датой в имени; проверьте, что копия не пустая. Периодичность: ежедневно при активной работе и обязательно перед обновлением программы.\nВосстановление: остановите сервер, положите копию поверх database.db, запустите сервер. Раз в квартал проверяйте восстановление на тестовой папке.\nПорт: по умолчанию 5000; если занят, программа возьмёт следующий свободный и напишет в консоли. Постоянно сменить порт: config.py, строка PORT."}, {"title": "Вход через Active Directory: настройка и проверка", "category": "Техническое", "order": 1, "body": "Active Directory подключается как дополнительный провайдер входа: при его недоступности программа падает на локальные пароли (если включён fallback), никто не оказывается заблокирован из-за проблем с доменом.\nНастройка (Настройки → Active Directory, нужно право auth.security):\nХост контроллера домена (имя или IP) и порт: 389 для «Без TLS» и «StartTLS», 636 для «LDAPS/SSL».\nДля самоподписанных сертификатов внутренних AD выбирайте StartTLS или LDAPS — проверка сертификата отключена намеренно.\nBase DN: корень поиска, например DC=company,DC=local.\nШаблон входа: для домена COMPANY пишите COMPANY\\%s, для почтового UPN — %s@company.local. Если оставить пустым, будет поиск по Base DN (требует разрешённый анонимный поиск либо проверочные данные).\nРоль по умолчанию для автоматически создаваемых доменных учёток.\nКнопка «Проверить связь» проходит шаги: библиотека → хост → TCP → TLS → bind → поиск, и останавливается на первой ошибке с пояснением.\nПоведение при входе: доменная учётка проверяется только в AD; локальная — у нас, но при совпадении с AD-паролем автоматически переводится на AD. Новый доменный пользователь создаётся автоматически с ролью по умолчанию, имя и email подтягиваются из AD. Доменные пароли у нас не хранятся вообще.\nАварийный режим: если AD недоступен, локальные пользователи входят как раньше; доменные учётки до восстановления AD войти не могут — это осознанное поведение, чтобы не подменять доменный пароль локальным."}, {"title": "Какие компьютеры и браузеры подходят", "category": "Техническое", "order": 2, "body": "Программа состоит из двух частей: сервер («мозг» с данными, один на отдел) и клиент (то, что люди видят в браузере).\nГде можно установить сервер (саму программу): Windows 10 / Server 2016 и новее — да; Windows 7 — можно со старой средой выполнения; Windows XP и Server 2003 — НЕТ (системам больше 15 лет, производитель их не поддерживает, современные программы не запускаются); Linux и Docker — да, отлично.\nГде могут работать люди: на любом компьютере локальной сети с современным браузером, включая Windows XP. Человек просто открывает браузер и вводит адрес сервера.\nБраузеры: Chrome, Firefox, новый Edge — да; Internet Explorer 11 — работает, но криво; Internet Explorer 7-10 — НЕТ (интерфейс ломается). На старых машинах ставьте Chrome или Firefox (на XP — Firefox 52 или Chrome 49, либо браузер Mypal).\nИнтернет не нужен: программа работает в локальной сети. Лицензии платить не нужно. Новое оборудование покупать не нужно, если есть один современный компьютер под сервер.\nПодробности и ответы на частые вопросы («почему нельзя на XP», «что если сервер сломается») — в разделе «Руководство», статья «Совместимость: какие компьютеры и браузеры подходят»."}, {"title": "Как подключить сторонний модуль", "category": "Техническое", "order": 3, "body": "Модули подключаются без правки ядра: положите папку модуля в modules/ и перезапустите программу. Ядро само найдёт модуль по файлу-паспорту module.json.\nПорядок: скопировать шаблон modules/_template в modules/<имя>; поменять в module.json ключ, название, версию и автора; переименовать blueprint в routes.py и подпапку шаблонов; описать права в perms.py; перезапустить сервер; включить модуль галочкой в Настройках; назначить права ролям.\nСторонние модули по умолчанию выключены. Битой модуль не роняет программу: при запуске будет предупреждение в консоли, система продолжит работать без него. Подробная пошаговая инструкция — в «Руководстве», раздел «Как подключить новый модуль (пошагово)»."}, {"title": "Работа на сервере и обновления", "category": "Техническое", "order": 4, "body": "Программу можно держать на отдельном сервере (Linux, виртуальная машина, Raspberry Pi). Тогда база одна на всех, а рабочий и домашний компьютер — просто клиенты с браузером.\nНастройки — в файле .env: APP_PORT (порт), APP_HOST, APP_SECRET_KEY (случайный ключ), APP_DEBUG (0 — сервер, 1 — разработка). В режиме сервера отладка выключена и порт фиксированный.\nНа Linux программа работает как служба modular-app: стартует при загрузке и поднимается после сбоя. Установка: ./deploy/install-service.sh. Лог: journalctl -u modular-app -f.\nОбновление на сервере — одна команда ./update.sh: копия базы, git pull, зависимости, установщик из tools/installers/, перезапуск службы, проверка HTTP. Установщик обязательно запускается на сервере — он правит базу.\nБэкап: ./backup.sh (горячая копия в data/backups/, старше 14 дней удаляются). Ежедневно — через cron. Копии периодически забирать за пределы сервера.\nПодробности и откат — в Руководстве, раздел «Работа на сервере»."}], "manual": [{"code": "hotelki", "title": null, "order": null, "body": "Раздел собирает потребности отдела и учитывает их выполнение. Хотелка — это служебная записка с адресатом: «кто → кому → что нужно».\nПодача: «Кто» — выпадающий список пользователей (по умолчанию вы); «Кому» — такой же список, а если нужного человека в нём нет, впишите имя или должность вручную; затем текст и «Отправить».\nПриватность: галочка «приватно» ограничивает видимость автором, адресатом и администратором. Это для случаев вроде «начальник отдела просит добавить функцию в программу» — зачем это видеть всему отделу? Приватные записи помечены замком, не попадают в чужие списки, историю и счётчики. Переключать видимость могут автор, адресат и админ.\nСтатусы: Новая, В работе, Сделано, Не нужно. Менять статус может роль с соответствующим правом (обычно руководитель). Отказ «Не нужно» при включённой настройке требует комментария с причиной.\nИстория и поиск работают с учётом приватности: чужие закрытые записи не показываются вообще."}, {"code": "ad", "title": "Active Directory: вход доменными учётками", "order": 75, "body": "Active Directory подключается как дополнительный провайдер входа: ядро от него не зависит и при недоступности домена падает на локальные пароли (если включён fallback).\nНастройка (Настройки → Active Directory, нужно право auth.security): хост и порт контроллера домена; защита соединения (без TLS / StartTLS / LDAPS); Base DN вида DC=company,DC=local; шаблон входа (ДОМЕН + обратный слэш + логин, либо %s@домен); фильтр поиска; роль по умолчанию для автосоздаваемых учёток.\nКнопка «Проверить связь» выполняет пошаговую диагностику: библиотека ldap3 → хост → TCP-соединение → TLS → bind (проверочным логином или анонимно) → поиск в Base DN. Останавливается на первом шаге с ошибкой и пишет пояснение. Проверочные логин и пароль нигде не сохраняются.\nПоведение при входе: доменная учётка проверяется только в AD; локальная — локально, но при совпадении пароля с AD автоматически переводится на доменный источник. Новый доменный пользователь создаётся автоматически (provisioning) с ролью по умолчанию; имя и email подтягиваются из AD; роль потом можно поменять в «Пользователи».\nАварийный режим: при недоступности AD локальные пользователи входят как раньше; доменные — не могут до восстановления связи. Это осознанное поведение: доменный пароль никогда не подменяется локальным."}, {"code": "sistemy", "title": "Совместимость: какие компьютеры и браузеры подходят", "order": 115, "body": "Программа состоит из двух частей. Серверная часть («мозг») хранит данные и выполняется на одном компьютере отдела. Клиентская часть — это то, что видят люди: страницы, которые открываются в браузере, как обычный сайт. Люди работают в браузере, а данные живут на сервере. Как в интернет-магазине: вы заходите через браузер, а сам магазин «живёт» на сервере.\nНА КАКИХ КОМПЬЮТЕРАХ МОЖНО УСТАНОВИТЬ СЕРВЕРНУЮ ЧАСТЬ (саму программу):\nWindows 10, Windows Server 2016 и новее — да, лучший вариант.\nWindows 7 — можно, но с оговорками: нужна старая версия среды выполнения (Python 3.8), технический специалист разберётся.\nWindows XP и Windows Server 2003 — НЕТ. Этим системам больше 15 лет, их производитель давно прекратил поддержку, и современные программы на них не запускаются. Это как пытаться установить современное приложение на телефон 2005 года: дело не в приложении, а в том, что система его не понимает.\nLinux (альтернатива Windows) — да, работает отлично, даже лучше Windows.\nDocker (специальная «упаковка» для программ) — да, лучший вариант: программа запускается одинаково на любом компьютере и не зависит от версии Windows.\nВАЖНО: старые компьютеры (Windows XP) МОЖНО использовать для работы! Просто не как сервер, а как рабочие места: человек открывает браузер, вводит адрес сервера (например, http://192.168.1.100:5000) и работает. Данные при этом хранятся на сервере.\nВ КАКИХ БРАУЗЕРАХ МОГУТ РАБОТАТЬ ЛЮДИ:\nGoogle Chrome, Mozilla Firefox, Microsoft Edge (новый, в Windows 10) — да, всё работает отлично.\nInternet Explorer 11 (последний IE) — работает, но криво: интерфейс может выглядеть хуже, чем задуман.\nInternet Explorer 7, 8, 9, 10 (старые) — НЕТ: интерфейс полностью ломается, кнопки наезжают друг на друга, списки превращаются в простой текст.\nНа Windows XP последние подходящие браузеры: Firefox 52 или Chrome 49 — работают нормально. Есть ещё Mypal (свежий браузер, сделанный специально для XP).\nЧТО ДЕЛАТЬ, ЕСЛИ У ЧЕЛОВЕКА СТАРЫЙ БРАУЗЕР: попросить технического специалиста установить Chrome или Firefox. Это бесплатно и занимает около 5 минут на компьютер. Проблема решается полностью.\nМИНИМУМ ДЛЯ ЗАПУСКА ПРОГРАММЫ:\nОдин современный компьютер под сервер (Windows 10 / Server 2016 / Linux).\nБраузеры Chrome или Firefox на всех рабочих местах.\nТехнический специалист на 2-3 часа для установки и настройки.\nНЕ НУЖНО: покупать новое оборудование (если есть современный компьютер); платить за лицензии (программа бесплатная); подключать интернет (работает в локальной сети); переучивать сотрудников (интерфейс простой, как обычный сайт).\nЧАСТЫЕ ВОПРОСЫ:\n«Можно ли запустить на XP?» — Работать в программе на XP можно (через браузер). Установить саму программу (серверную часть) на XP нельзя.\n«У нас только старые серверы (Server 2003), что делать?» — Серверная часть на них не запустится. Варианты: выделить современный компьютер; установить на старый сервер Linux (бесплатно); арендовать облачный сервер (платно, но без своего железа).\n«Нужен ли интернет?» — Нет, программа работает внутри локальной сети офиса.\n«Что если сервер сломается?» — Все данные лежат в одном файле; технический специалист делает резервные копии (копирует файл раз в день), после поломки данные восстанавливаются из копии. Порядок описан в разделе «Резервные копии и восстановление».\n«Могут ли люди работать одновременно?» — Да, в этом смысл программы: несколько человек работают одновременно, никто никого не блокирует (в отличие от Excel-таблицы, где один открыл файл — остальные ждут).\n«Это безопасно?» — Программа работает внутри вашей сети, из интернета её не видно (если специально не настраивать). Есть пароли, роли и журналы действий, как в любой серьёзной системе."}, {"code": "moduli-dev", "title": "Как подключить новый модуль (пошагово)", "order": 85, "body": "Модуль — это папка в modules/ с паспортом module.json. Ядро находит такие папки само, править ядро не нужно.\nШаг 1. Скопируйте папку modules/_template в modules/<имя_модуля> (имя латиницей, без пробелов).\nШаг 2. В module.json поменяйте key (равно имени папки), name (русское название для меню), version, author, description. Поле default_enabled: false означает, что модуль после установки выключен и включается галочкой в Настройках — это правильно для сторонних модулей.\nШаг 3. В routes.py переименуйте blueprint: primer_bp на <имя>_bp и url_prefix на /<имя>. В models.py переименуйте таблицы, чтобы не совпадали с другими модулями.\nШаг 4. Шаблоны держите в подпапке templates/<имя_модуля>/ — иначе страницы разных модулей начнут путаться (проверено на практике).\nШаг 5. В perms.py опишите права модуля: код, группа, человеческое описание. Они сами появятся на экране «Роли» галочками.\nШаг 6. Перезапустите python run.py. Модуль появится в Настройках в списке «Доступные модули» с версией и автором из паспорта.\nШаг 7. Включите галочку, сохраните, перезапустите сервер. Назначьте права ролям на экране «Роли».\nБезопасность: если код стороннего модуля битой, программа при запуске напечатает предупреждение и продолжит работать без этого модуля — вся система не падает. Сторонние модули по умолчанию выключены, поэтому случайная папка в modules/ не откроет никому доступ.\nПо регламенту после подключения модуля обновите журнал изменений и, если модуль виден людям, создайте релиз; статьи справки и разделы руководства дополните описанием нового модуля."}, {"code": "tables-konstruktor", "title": "Конструктор таблиц: пошагово", "order": 88, "body": "Конструктор таблиц даёт пользователю создавать таблицы без программиста: «Таблицы» → «Создать таблицу» (название и ключ латиницей) → «Колонки и формулы» → «Доступ (роли × колонки)».\nКолонки: типы текст, число, дата, список (варианты через запятую), вычисляемая и ссылка на другую таблицу. Вычисляемые настраиваются конструктором: вид (арифметика, склейка, дней между дат, ЕСЛИ…ТО…ИНАЧЕ), операция, операнды ключами колонок или literals; пример результата показывается на первой строке при сохранении. Вычисляемые колонки не редактируются пользователями (значок ⚙), что защищает «формулы» от случайной порчи — главная болезнь Excel.\nПрава: матрица «роль × колонка» на экране «Доступ»: видеть таблицу, создавать строки, удалять, и галочки ✎ на каждую редактируемую колонку. Права хранятся в базе, а не в коде, поэтому новые колонки сразу можно раздавать ролям. Суперпользователь обходит матрицу.\nЭксплуатация: история по каждой клетке («История клеток»), корзина на 30 дней с восстановлением и удалением навсегда (автоочистка просроченного), счётчики-карточки над таблицей (сумма/количество с условием). Удаление таблицы пишет резервную копию в data/backups/ и запись в журнал изменений.\nРегламент: после создания боевой таблицы опишите её в Справке (назначение, кто ведёт) и добавьте релиз, если таблица видна многим.\n\nИмпорт Excel (.xlsx): колонки сопоставляются по названиям заголовков, несовпавшие заголовки могут стать новыми колонками типа «Текст»; строки добавляются, существующие не затираются. Типы колонок в интерфейсе показаны по‑русски (внутри хранятся коды text/number/date/list/computed/ref)."}, {"code": "server", "title": "Работа на сервере: служба, обновления, бэкапы", "order": 112, "body": "Программу можно держать на отдельном компьютере-сервере (Linux, виртуальная машина или Raspberry Pi). Тогда данные живут в одном месте, а рабочий и домашний компьютер — просто клиенты: открыл браузер, ввёл адрес сервера, работаешь. Больше не нужно переносить файл базы между машинами.\nРЕЖИМЫ. Настройки лежат в файле .env в папке программы (в Git не попадает): APP_PORT — порт; APP_HOST — адрес прослушивания; APP_SECRET_KEY — секретный ключ сессий (должен быть случайным); APP_DEBUG — режим. APP_DEBUG=0 — сервер: отладка выключена, порт фиксированный (если занят — честная ошибка, адрес не «уезжает»), работает промышленный WSGI-сервер waitress. APP_DEBUG=1 — разработка: отладка и автоподбор порта, как раньше. На боевом сервере отладка должна быть выключена: в режиме отладки через браузер можно выполнить произвольный код на сервере.\nСЛУЖБА. На Linux программа работает как служба systemd под именем modular-app: стартует сама при загрузке компьютера и поднимается после сбоя. Установка один раз: ./deploy/install-service.sh (скрипт сам подставит пользователя и путь). Управление: sudo systemctl restart modular-app — перезапуск; systemctl status modular-app — состояние; journalctl -u modular-app -f — живой лог. Открытое окно терминала больше не нужно.\nОБНОВЛЕНИЯ. Код правится на рабочем или домашнем компьютере и публикуется в Git. Установщик кладётся в tools/installers/install.py, поэтому приезжает на сервер вместе с кодом. На сервере достаточно одной команды: ./update.sh. Она делает: резервную копию базы, создаёт .env при отсутствии, git pull, обновление зависимостей, запуск установщика (в том числе миграции базы и синхронизацию документации), перезапуск службы и проверку HTTP. Важно: установщик запускается именно на сервере, потому что он правит базу; если прогнать его только на рабочем компьютере, боевая база не получит новых колонок.\nБЭКАПЫ. ./backup.sh делает горячую копию базы в data/backups/ (безопасно даже при работающем сервере) и удаляет копии старше 14 дней. Ежедневный запуск по расписанию: crontab -e и строка 0 3 * * * /home/пользователь/modular-app/backup.sh. Копии нужно периодически забирать за пределы сервера: если умрёт диск, умрут и копии на нём.\nОТКАТ. Если обновление сломало работу: git log --oneline -10, затем git reset --hard <хеш> и sudo systemctl restart modular-app. На сервере код руками не правится, поэтому такой откат безопасен. Если навредила миграция базы: остановить службу, положить нужную копию из data/backups/ поверх data/database.db, запустить службу. Именно поэтому update.sh делает копию ДО установки.\nДВА КОМПЬЮТЕРА. Мастерских может быть две (дом и работа), сервер один. У каждой мастерской своя тестовая база, боевая — только на сервере. Правило: перед началом работы — Pull, закончил — сразу Commit и Push, иначе две мастерские подерутся за один файл. Если с работы нет доступа к серверу, разработка всё равно возможна: проверяешь локально на тестовой базе, коммитишь, а выкладываешь на сервер позже."}]}'''
_DATA = _json.loads(_RAW)


def apply():
    """Приводит справку и руководство к эталону из Git. Идемпотентен."""
    from core.app import db
    from modules.help.models import HelpArticle, CATEGORIES
    from modules.manual.models import ManualSection
    n_h = 0
    for rec in _DATA["help"]:
        cat = rec.get("category") or ""
        if CATEGORIES and cat not in CATEGORIES:
            cat = CATEGORIES[0]
        a = HelpArticle.query.filter_by(title=rec["title"]).first()
        if not a:
            a = HelpArticle(title=rec["title"], category=cat,
                            order=rec.get("order", 0), body=rec["body"],
                            edited_by="docs_seed")
            db.session.add(a)
        else:
            a.category = cat
            a.order = rec.get("order", a.order)
            a.body = rec["body"]
            a.edited_by = "docs_seed"
            a.updated_at = _dt.utcnow()
        n_h += 1
    db.session.commit()

    n_m = 0
    for rec in _DATA["manual"]:
        s = ManualSection.query.filter_by(code=rec["code"]).first()
        if not s:
            s = ManualSection(code=rec["code"],
                              title=rec.get("title") or rec["code"],
                              order=rec.get("order", 0), body=rec["body"],
                              updated_by="docs_seed")
            db.session.add(s)
        else:
            if rec.get("title"):
                s.title = rec["title"]
            if rec.get("order") is not None:
                s.order = rec["order"]
            s.body = rec["body"]
            s.updated_by = "docs_seed"
            s.updated_at = _dt.utcnow()
        n_m += 1
    db.session.commit()
    return n_h, n_m
